(function (window) {
  function escapeHtml(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }
  window.katex = window.katex || {
    renderToString: function (tex, options) {
      var display = options && options.displayMode;
      return '<span class="' + (display ? 'katex katex-display' : 'katex') + '">' + escapeHtml(tex) + '</span>';
    }
  };
})(window);
